begin;

create or replace function private.fighter_set_subclass_level_v2(
  p_template_id uuid,p_level integer,p_mechanics jsonb,p_choices jsonb default '[]'::jsonb
) returns void language plpgsql security definer set search_path='' as $$
declare v_spells jsonb;
begin
  select coalesce(jsonb_agg(m order by ord) filter(where m->>'type'='spell'),'[]'::jsonb)
    into v_spells
  from public.rule_template_levels l
  cross join lateral jsonb_array_elements(coalesce(l.mechanics,'[]'::jsonb)) with ordinality q(m,ord)
  where l.template_id=p_template_id and l.level=p_level;

  insert into public.rule_template_levels(template_id,level,mechanics,choices)
  values(p_template_id,p_level,coalesce(v_spells,'[]'::jsonb)||coalesce(p_mechanics,'[]'::jsonb),coalesce(p_choices,'[]'::jsonb))
  on conflict(template_id,level) do update set
    mechanics=excluded.mechanics,
    choices=excluded.choices;
end;
$$;

create or replace function private.fighter_patch_feature_text(
  p_template_id uuid,p_level integer,p_source_key text,p_label text,p_description text
) returns void language plpgsql security definer set search_path='' as $$
begin
  update public.rule_template_levels l
  set mechanics=coalesce((
    select jsonb_agg(
      case when m->>'type'='grant' and m->>'target'='feature' and m->>'sourceKey'=p_source_key
        then jsonb_set(jsonb_set(m,'{payload,label}',to_jsonb(p_label),true),'{payload,description}',to_jsonb(p_description),true)
        else m end
      order by ord
    )
    from jsonb_array_elements(coalesce(l.mechanics,'[]'::jsonb)) with ordinality q(m,ord)
  ),'[]'::jsonb)
  where l.template_id=p_template_id and l.level=p_level;
end;
$$;

create or replace function private.apply_fighter_completion(p_campaign_id uuid)
returns void
language plpgsql
security definer
set search_path=''
as $$
declare
  v_fighter uuid;
  v_arcane_archer uuid;
  v_battle_master uuid;
  v_cavalier uuid;
  v_champion uuid;
  v_echo uuid;
  v_eldritch uuid;
  v_psi uuid;
  v_banneret uuid;
  v_rune uuid;
  v_samurai uuid;
  v_con_formula jsonb := '{"kind":"max","values":[{"kind":"literal","value":1},{"kind":"reference","key":"abilities.constitution.modifier"}]}'::jsonb;
  v_cha_formula jsonb := '{"kind":"max","values":[{"kind":"literal","value":1},{"kind":"reference","key":"abilities.charisma.modifier"}]}'::jsonb;
begin
  select id into v_fighter from public.rule_templates where campaign_id=p_campaign_id and catalog_key='class:fighter' and kind='class' and is_active order by version desc limit 1;
  if v_fighter is null then return; end if;

  update public.rule_templates set
    catalog_revision='xphb-2024-fighter-precision-v2-ru',
    mechanical_summary='Воин 2024: точные русские карточки базовых способностей; конечные запасы и числовая прогрессия считаются CE, а сценические условия остаются явно описанными правилами.',
    rules_meta=coalesce(rules_meta,'{}'::jsonb)||jsonb_build_object('fighter_completion_pack',true,'ru_rules_audit',true,'persistent_level_choices',true),
    updated_at=now()
  where id=v_fighter;

  perform private.fighter_patch_feature_text(v_fighter,2,'tactical-mind','Тактическое мышление','После проваленной проверки характеристики можно направить Второе дыхание на Тактическое мышление: бросьте 1к10 и добавьте результат к проверке. Если после добавления проверка всё равно провалена, использование Второго дыхания не расходуется.');
  perform private.fighter_patch_feature_text(v_fighter,5,'tactical-shift','Тактическое смещение','Когда используете Второе дыхание бонусным действием, можно в рамках этого же бонусного действия переместиться на расстояние до половины Скорости, не провоцируя атаки по возможности.');
  perform private.fighter_patch_feature_text(v_fighter,9,'tactical-master','Тактическое решение','Когда атакуете оружием, для которого умеете применять свойство Мастерства, можно для этой атаки заменить обычное свойство Мастерства этого оружия на Push, Sap или Slow.');
  perform private.fighter_patch_feature_text(v_fighter,13,'studied-attacks','Изучающие выпады','Если атака по существу промахнулась, следующая атака по этому же существу до конца следующего хода Воина совершается с преимуществом.');

  select id into v_arcane_archer from public.rule_templates where campaign_id=p_campaign_id and catalog_key='subclass:fighter:arcane-archer' and is_active order by version desc limit 1;
  select id into v_battle_master from public.rule_templates where campaign_id=p_campaign_id and catalog_key='subclass:fighter:battle-master' and is_active order by version desc limit 1;
  select id into v_cavalier from public.rule_templates where campaign_id=p_campaign_id and catalog_key='subclass:fighter:cavalier' and is_active order by version desc limit 1;
  select id into v_champion from public.rule_templates where campaign_id=p_campaign_id and catalog_key='subclass:fighter:champion' and is_active order by version desc limit 1;
  select id into v_echo from public.rule_templates where campaign_id=p_campaign_id and catalog_key='subclass:fighter:echo-knight' and is_active order by version desc limit 1;
  select id into v_eldritch from public.rule_templates where campaign_id=p_campaign_id and catalog_key='subclass:fighter:eldritch-knight' and is_active order by version desc limit 1;
  select id into v_psi from public.rule_templates where campaign_id=p_campaign_id and catalog_key='subclass:fighter:psi-warrior' and is_active order by version desc limit 1;
  select id into v_banneret from public.rule_templates where campaign_id=p_campaign_id and catalog_key='subclass:fighter:banneret' and is_active order by version desc limit 1;
  select id into v_rune from public.rule_templates where campaign_id=p_campaign_id and catalog_key='subclass:fighter:rune-knight' and is_active order by version desc limit 1;
  select id into v_samurai from public.rule_templates where campaign_id=p_campaign_id and catalog_key='subclass:fighter:samurai' and is_active order by version desc limit 1;

  if v_arcane_archer is not null then
    update public.rule_templates set
      catalog_revision='xgte-2017-arcane-archer-ru-precision-v2',
      mechanical_summary='Мистический лучник: два использования Магического выстрела за короткий или долгий отдых; конкретные варианты выбираются постоянно и расширяются с уровнем Воина.',
      updated_at=now()
    where id=v_arcane_archer;

    perform private.fighter_set_subclass_level_v2(v_arcane_archer,3,jsonb_build_array(
      private.fighter_feature('fighter-aa-l3','arcane-shot','subclass:fighter:arcane-archer:arcane-shot','Магический выстрел','На 3 уровне выберите 2 варианта Магического выстрела. Один раз за ход, когда выполняется условие выбранного варианта, можно потратить 1 использование Магического выстрела. Всего 2 использования; они полностью возвращаются после короткого или долгого отдыха. Сл спасброска Магического выстрела = 8 + бонус мастерства + модификатор Интеллекта.'),
      private.fighter_resource('fighter-aa-pool','arcane-shot','arcane_shot','Магический выстрел','2'::jsonb,'{"triggers":["short_rest","long_rest"],"restore":"full"}'::jsonb,3,'REPLACE')
    ),jsonb_build_array('{"key":"arcane_shot_options","label":"Варианты Магического выстрела","target":"trait","options":["banishing","beguiling","bursting","enfeebling","grasping","piercing","seeking","shadow"],"count":2,"count_by_level":{"7":3,"10":4,"15":5,"18":6},"option_labels":{"banishing":"Изгоняющая стрела","beguiling":"Обманная стрела","bursting":"Взрывная стрела","enfeebling":"Ослабляющая стрела","grasping":"Сжимающая стрела","piercing":"Пронзающая стрела","seeking":"Ищущая стрела","shadow":"Теневая стрела"},"option_mechanics":{"banishing":[{"id":"fighter-aa-banishing-feature","type":"grant","target":"feature","key":"subclass:fighter:arcane-archer:shot:banishing","sourceKey":"arcane-shot:banishing","payload":{"label":"Изгоняющая стрела","description":"Когда стрела попадает по существу, оно совершает спасбросок Харизмы. При провале цель изгоняется в безопасное место в Стране Фей: её Скорость становится 0, и она недееспособна до конца своего следующего хода, после чего возвращается. С 18 уровня при попадании дополнительно наносится 2к6 урона силовым полем."}},{"id":"fighter-aa-banishing-use","type":"action","sourceKey":"arcane-shot:banishing","key":"arcane_shot_banishing","label":"Изгоняющая стрела","economy":"triggered","range":{"kind":"self"},"presentation":{"tone":"amber","icon":"◆","display":"counter","priority":85},"resourceCosts":[{"key":"arcane_shot","amount":1}],"tags":["arcane_archer","arcane_shot"]}],"beguiling":[{"id":"fighter-aa-beguiling-feature","type":"grant","target":"feature","key":"subclass:fighter:arcane-archer:shot:beguiling","sourceKey":"arcane-shot:beguiling","payload":{"label":"Обманная стрела","description":"При попадании цель получает дополнительно 2к6 психического урона. Выберите союзника в пределах 30 футов от цели: при провале спасброска Мудрости цель очарована им до начала вашего следующего хода; эффект заканчивается раньше, если этот союзник атакует цель, наносит ей урон или заставляет совершить спасбросок. С 18 уровня дополнительный урон 4к6."}},{"id":"fighter-aa-beguiling-use","type":"action","sourceKey":"arcane-shot:beguiling","key":"arcane_shot_beguiling","label":"Обманная стрела","economy":"triggered","range":{"kind":"self"},"presentation":{"tone":"amber","icon":"◆","display":"counter","priority":85},"resourceCosts":[{"key":"arcane_shot","amount":1}],"tags":["arcane_archer","arcane_shot"]}],"bursting":[{"id":"fighter-aa-bursting-feature","type":"grant","target":"feature","key":"subclass:fighter:arcane-archer:shot:bursting","sourceKey":"arcane-shot:bursting","payload":{"label":"Взрывная стрела","description":"Сразу после попадания цель и каждое другое существо в пределах 10 футов от неё получают 2к6 урона силовым полем. Спасброска нет. С 18 уровня урон 4к6."}},{"id":"fighter-aa-bursting-use","type":"action","sourceKey":"arcane-shot:bursting","key":"arcane_shot_bursting","label":"Взрывная стрела","economy":"triggered","range":{"kind":"self"},"presentation":{"tone":"amber","icon":"◆","display":"counter","priority":85},"resourceCosts":[{"key":"arcane_shot","amount":1}],"tags":["arcane_archer","arcane_shot"]}],"enfeebling":[{"id":"fighter-aa-enfeebling-feature","type":"grant","target":"feature","key":"subclass:fighter:arcane-archer:shot:enfeebling","sourceKey":"arcane-shot:enfeebling","payload":{"label":"Ослабляющая стрела","description":"При попадании цель получает дополнительно 2к6 некротического урона и совершает спасбросок Телосложения. При провале урон её атак оружием уменьшается вдвое до начала вашего следующего хода. С 18 уровня дополнительный урон 4к6."}},{"id":"fighter-aa-enfeebling-use","type":"action","sourceKey":"arcane-shot:enfeebling","key":"arcane_shot_enfeebling","label":"Ослабляющая стрела","economy":"triggered","range":{"kind":"self"},"presentation":{"tone":"amber","icon":"◆","display":"counter","priority":85},"resourceCosts":[{"key":"arcane_shot","amount":1}],"tags":["arcane_archer","arcane_shot"]}],"grasping":[{"id":"fighter-aa-grasping-feature","type":"grant","target":"feature","key":"subclass:fighter:arcane-archer:shot:grasping","sourceKey":"arcane-shot:grasping","payload":{"label":"Сжимающая стрела","description":"При попадании цель получает дополнительно 2к6 урона ядом, её Скорость уменьшается на 10 футов, и первый раз за ход, когда она перемещается хотя бы на 1 фут без телепортации, получает 2к6 рубящего урона. Существо в пределах досягаемости может действием снять путы успешной проверкой Силы (Атлетика) против Сл Магического выстрела. Иначе путы держатся 1 минуту или до вашего следующего применения этой опции. С 18 уровня оба вида дополнительного урона 4к6."}},{"id":"fighter-aa-grasping-use","type":"action","sourceKey":"arcane-shot:grasping","key":"arcane_shot_grasping","label":"Сжимающая стрела","economy":"triggered","range":{"kind":"self"},"presentation":{"tone":"amber","icon":"◆","display":"counter","priority":85},"resourceCosts":[{"key":"arcane_shot","amount":1}],"tags":["arcane_archer","arcane_shot"]}],"piercing":[{"id":"fighter-aa-piercing-feature","type":"grant","target":"feature","key":"subclass:fighter:arcane-archer:shot:piercing","sourceKey":"arcane-shot:piercing","payload":{"label":"Пронзающая стрела","description":"Вместо броска атаки стрела проходит линией шириной 1 фут и длиной 30 футов, проходит сквозь объекты и игнорирует укрытие. Каждое существо в линии совершает спасбросок Ловкости: при провале получает урон как от попадания стрелой + 1к6 колющего, при успехе — половину. С 18 уровня дополнительный колющий урон 2к6."}},{"id":"fighter-aa-piercing-use","type":"action","sourceKey":"arcane-shot:piercing","key":"arcane_shot_piercing","label":"Пронзающая стрела","economy":"triggered","range":{"kind":"self"},"presentation":{"tone":"amber","icon":"◆","display":"counter","priority":85},"resourceCosts":[{"key":"arcane_shot","amount":1}],"tags":["arcane_archer","arcane_shot"]}],"seeking":[{"id":"fighter-aa-seeking-feature","type":"grant","target":"feature","key":"subclass:fighter:arcane-archer:shot:seeking","sourceKey":"arcane-shot:seeking","payload":{"label":"Ищущая стрела","description":"Вместо броска атаки выберите существо, которое видели за последнюю минуту. Стрела огибает углы и игнорирует половинное и три четверти укрытие, если цель в дальности оружия и существует путь для стрелы. Цель совершает спасбросок Ловкости: при провале получает урон как от попадания + 1к6 силового урона, а вы узнаёте её текущее местоположение; при успехе получает половину и местоположение не раскрывается. С 18 уровня дополнительный урон 2к6."}},{"id":"fighter-aa-seeking-use","type":"action","sourceKey":"arcane-shot:seeking","key":"arcane_shot_seeking","label":"Ищущая стрела","economy":"triggered","range":{"kind":"self"},"presentation":{"tone":"amber","icon":"◆","display":"counter","priority":85},"resourceCosts":[{"key":"arcane_shot","amount":1}],"tags":["arcane_archer","arcane_shot"]}],"shadow":[{"id":"fighter-aa-shadow-feature","type":"grant","target":"feature","key":"subclass:fighter:arcane-archer:shot:shadow","sourceKey":"arcane-shot:shadow","payload":{"label":"Теневая стрела","description":"При попадании цель получает дополнительно 2к6 психического урона и совершает спасбросок Мудрости. При провале до начала вашего следующего хода она не видит ничего дальше 5 футов. С 18 уровня дополнительный урон 4к6."}},{"id":"fighter-aa-shadow-use","type":"action","sourceKey":"arcane-shot:shadow","key":"arcane_shot_shadow","label":"Теневая стрела","economy":"triggered","range":{"kind":"self"},"presentation":{"tone":"amber","icon":"◆","display":"counter","priority":85},"resourceCosts":[{"key":"arcane_shot","amount":1}],"tags":["arcane_archer","arcane_shot"]}]}}'::jsonb));
    perform private.fighter_set_subclass_level_v2(v_arcane_archer,7,jsonb_build_array(
      private.fighter_feature('fighter-aa-magic-arrow','magic-arrow','subclass:fighter:arcane-archer:magic-arrow','Зачарованная стрела','Немагическая стрела, выпущенная из короткого или длинного лука, считается магической для преодоления сопротивления и иммунитета к немагическим атакам.'),
      private.fighter_feature('fighter-aa-curving','curving-shot','subclass:fighter:arcane-archer:curving-shot','Странствующая стрела','Если магическая стрела промахнулась, бонусным действием можно перенаправить её в другую цель в пределах 60 футов от первоначальной цели и повторить атаку.')
    ));
    perform private.fighter_set_subclass_level_v2(v_arcane_archer,15,jsonb_build_array(private.fighter_feature('fighter-aa-ready','ever-ready-shot','subclass:fighter:arcane-archer:ever-ready','Выстрел всегда наготове','Если при броске инициативы не осталось использований Магического выстрела, восстановите 1.')));
  end if;

  if v_battle_master is not null then
    update public.rule_templates set
      name='Мастер боя',
      catalog_revision='xphb-2024-battle-master-ru-precision-v2',
      mechanical_summary='Мастер боя 2024: отдельный запас костей превосходства, отдельный размер кости, постоянный список выбранных приёмов и точная механика Познай своего врага.',
      updated_at=now()
    where id=v_battle_master;

    perform private.fighter_set_subclass_level_v2(v_battle_master,3,jsonb_build_array(
      private.fighter_feature('fighter-bm-l3','combat-superiority','subclass:fighter:battle-master:combat-superiority','Боевое превосходство','Выберите 3 приёма. Приём, требующий кость превосходства, расходует одну кость, если в его тексте не сказано иначе. Сл спасброска приёма = 8 + бонус мастерства + модификатор Силы или Ловкости, на ваш выбор.'),
      private.fighter_feature('fighter-bm-student','student-of-war','subclass:fighter:battle-master:student-of-war','Изучающий войну','Получите владение одним видом ремесленных инструментов и одним навыком из списка навыков Воина 1 уровня, которыми ещё не владеете.'),
      private.fighter_resource('fighter-bm-dice-l3','combat-superiority','superiority_dice','Кости превосходства','4'::jsonb,'{"triggers":["short_rest","long_rest"],"restore":"full"}'::jsonb,3,'REPLACE'),
      private.fighter_value('fighter-bm-die-l3','combat-superiority','superiority_die','Кость превосходства','8'::jsonb,3,'REPLACE')
    ),jsonb_build_array('{"key":"battle_master_maneuvers","label":"Приёмы Мастера боя","target":"trait","options":["ambush","bait_and_switch","commanders_strike","commanding_presence","disarming_attack","distracting_strike","evasive_footwork","feinting_attack","goading_attack","lunging_attack","maneuvering_attack","menacing_attack","parry","precision_attack","pushing_attack","rally","riposte","sweeping_attack","tactical_assessment","trip_attack"],"count":3,"count_by_level":{"7":5,"10":7,"15":9},"option_labels":{"ambush":"Засада","bait_and_switch":"Подмена","commanders_strike":"Удар командующего","commanding_presence":"Командирский напор","disarming_attack":"Обезоруживающая атака","distracting_strike":"Отвлекающий удар","evasive_footwork":"Активное уклонение","feinting_attack":"Атака с финтом","goading_attack":"Провоцирующая атака","lunging_attack":"Атака с выпадом","maneuvering_attack":"Атака с манёвром","menacing_attack":"Атака с угрозой","parry":"Парирование","precision_attack":"Точная атака","pushing_attack":"Толкающая атака","rally":"Сплочение","riposte":"Ответный удар","sweeping_attack":"Рассекающая атака","tactical_assessment":"Тактическая оценка","trip_attack":"Опрокидывающая атака"},"option_mechanics":{"ambush":[{"id":"fighter-bm-maneuver-ambush-feature","type":"grant","target":"feature","key":"subclass:fighter:battle-master:maneuver:ambush","sourceKey":"maneuver:ambush","payload":{"label":"Засада","description":"Когда вы совершаете проверку Ловкости (Скрытность) или бросок инициативы и не недееспособны, можно потратить 1 кость превосходства и добавить её результат к броску."}},{"id":"fighter-bm-maneuver-ambush-use","type":"action","sourceKey":"maneuver:ambush","key":"battle_master_ambush","label":"Засада","economy":"triggered","range":{"kind":"self"},"resourceCosts":[{"key":"superiority_dice","amount":1}]}],"bait_and_switch":[{"id":"fighter-bm-maneuver-bait-feature","type":"grant","target":"feature","key":"subclass:fighter:battle-master:maneuver:bait-and-switch","sourceKey":"maneuver:bait-and-switch","payload":{"label":"Подмена","description":"Когда на своём ходу вы находитесь в пределах 5 футов от существа и имеете хотя бы 5 футов движения, потратьте 1 кость превосходства: поменяйтесь местами с согласным существом, не провоцируя атаки по возможности. Затем выберите себя или это существо; до начала вашего следующего хода выбранная цель получает бонус к КД, равный результату кости превосходства."}},{"id":"fighter-bm-maneuver-bait-use","type":"action","sourceKey":"maneuver:bait-and-switch","key":"battle_master_bait_and_switch","label":"Подмена","economy":"movement_modifier","range":{"kind":"self"},"resourceCosts":[{"key":"superiority_dice","amount":1}]}],"commanders_strike":[{"id":"fighter-bm-maneuver-commanders-feature","type":"grant","target":"feature","key":"subclass:fighter:battle-master:maneuver:commanders-strike","sourceKey":"maneuver:commanders-strike","payload":{"label":"Удар командующего","description":"Когда совершаете действие Атака на своём ходу, замените одну атаку командой союзнику. Потратьте бонусное действие и 1 кость превосходства; выбранное дружественное существо, которое видит или слышит вас, может реакцией совершить одну атаку оружием и добавить кость превосходства к урону при попадании."}},{"id":"fighter-bm-maneuver-commanders-use","type":"action","sourceKey":"maneuver:commanders-strike","key":"battle_master_commanders_strike","label":"Удар командующего","economy":"bonus_action","range":{"kind":"self"},"resourceCosts":[{"key":"superiority_dice","amount":1}]}],"commanding_presence":[{"id":"fighter-bm-maneuver-presence-feature","type":"grant","target":"feature","key":"subclass:fighter:battle-master:maneuver:commanding-presence","sourceKey":"maneuver:commanding-presence","payload":{"label":"Командирский напор","description":"Когда совершаете проверку Харизмы (Запугивание), Харизмы (Выступление) или Харизмы (Убеждение), можно потратить 1 кость превосходства и добавить её результат к проверке."}},{"id":"fighter-bm-maneuver-presence-use","type":"action","sourceKey":"maneuver:commanding-presence","key":"battle_master_commanding_presence","label":"Командирский напор","economy":"triggered","range":{"kind":"self"},"resourceCosts":[{"key":"superiority_dice","amount":1}]}],"disarming_attack":[{"id":"fighter-bm-maneuver-disarm-feature","type":"grant","target":"feature","key":"subclass:fighter:battle-master:maneuver:disarming-attack","sourceKey":"maneuver:disarming-attack","payload":{"label":"Обезоруживающая атака","description":"Когда попадаете по существу атакой оружием, потратьте 1 кость превосходства: добавьте её к урону. Цель совершает спасбросок Силы; при провале роняет один предмет по вашему выбору, который держит. Предмет падает у её ног."}},{"id":"fighter-bm-maneuver-disarm-use","type":"action","sourceKey":"maneuver:disarming-attack","key":"battle_master_disarming_attack","label":"Обезоруживающая атака","economy":"triggered","range":{"kind":"self"},"resourceCosts":[{"key":"superiority_dice","amount":1}]}],"distracting_strike":[{"id":"fighter-bm-maneuver-distract-feature","type":"grant","target":"feature","key":"subclass:fighter:battle-master:maneuver:distracting-strike","sourceKey":"maneuver:distracting-strike","payload":{"label":"Отвлекающий удар","description":"Когда попадаете по существу атакой оружием, потратьте 1 кость превосходства и добавьте её к урону. Следующий бросок атаки другого существа по этой цели до начала вашего следующего хода совершается с преимуществом."}},{"id":"fighter-bm-maneuver-distract-use","type":"action","sourceKey":"maneuver:distracting-strike","key":"battle_master_distracting_strike","label":"Отвлекающий удар","economy":"triggered","range":{"kind":"self"},"resourceCosts":[{"key":"superiority_dice","amount":1}]}],"evasive_footwork":[{"id":"fighter-bm-maneuver-evasive-feature","type":"grant","target":"feature","key":"subclass:fighter:battle-master:maneuver:evasive-footwork","sourceKey":"maneuver:evasive-footwork","payload":{"label":"Активное уклонение","description":"Когда перемещаетесь, можно потратить 1 кость превосходства, бросить её и добавить результат к КД до окончания перемещения."}},{"id":"fighter-bm-maneuver-evasive-use","type":"action","sourceKey":"maneuver:evasive-footwork","key":"battle_master_evasive_footwork","label":"Активное уклонение","economy":"movement_modifier","range":{"kind":"self"},"resourceCosts":[{"key":"superiority_dice","amount":1}]}],"feinting_attack":[{"id":"fighter-bm-maneuver-feint-feature","type":"grant","target":"feature","key":"subclass:fighter:battle-master:maneuver:feinting-attack","sourceKey":"maneuver:feinting-attack","payload":{"label":"Атака с финтом","description":"Бонусным действием выберите существо в пределах 5 футов и потратьте 1 кость превосходства. Следующая атака по нему в этот ход совершается с преимуществом; если она попадает, добавьте кость превосходства к урону."}},{"id":"fighter-bm-maneuver-feint-use","type":"action","sourceKey":"maneuver:feinting-attack","key":"battle_master_feinting_attack","label":"Атака с финтом","economy":"bonus_action","range":{"kind":"self"},"resourceCosts":[{"key":"superiority_dice","amount":1}]}],"goading_attack":[{"id":"fighter-bm-maneuver-goad-feature","type":"grant","target":"feature","key":"subclass:fighter:battle-master:maneuver:goading-attack","sourceKey":"maneuver:goading-attack","payload":{"label":"Провоцирующая атака","description":"Когда попадаете по существу атакой оружием, потратьте 1 кость превосходства и добавьте её к урону. Цель совершает спасбросок Мудрости; при провале до конца вашего следующего хода её атаки по другим целям совершаются с помехой."}},{"id":"fighter-bm-maneuver-goad-use","type":"action","sourceKey":"maneuver:goading-attack","key":"battle_master_goading_attack","label":"Провоцирующая атака","economy":"triggered","range":{"kind":"self"},"resourceCosts":[{"key":"superiority_dice","amount":1}]}],"lunging_attack":[{"id":"fighter-bm-maneuver-lunge-feature","type":"grant","target":"feature","key":"subclass:fighter:battle-master:maneuver:lunging-attack","sourceKey":"maneuver:lunging-attack","payload":{"label":"Атака с выпадом","description":"Бонусным действием потратьте 1 кость превосходства и совершите действие Атака. До конца этого хода досягаемость ваших атак ближнего боя увеличивается на 5 футов; если за действие Атака вы попали атакой ближнего боя, добавьте кость превосходства к урону этой атаки."}},{"id":"fighter-bm-maneuver-lunge-use","type":"action","sourceKey":"maneuver:lunging-attack","key":"battle_master_lunging_attack","label":"Атака с выпадом","economy":"bonus_action","range":{"kind":"self"},"resourceCosts":[{"key":"superiority_dice","amount":1}]}],"maneuvering_attack":[{"id":"fighter-bm-maneuver-maneuver-feature","type":"grant","target":"feature","key":"subclass:fighter:battle-master:maneuver:maneuvering-attack","sourceKey":"maneuver:maneuvering-attack","payload":{"label":"Атака с манёвром","description":"Когда попадаете по существу атакой оружием, потратьте 1 кость превосходства и добавьте её к урону. Выберите дружественное существо, которое видит или слышит вас; оно может реакцией переместиться на расстояние до половины своей Скорости, не провоцируя атаки по возможности от цели вашей атаки."}},{"id":"fighter-bm-maneuver-maneuver-use","type":"action","sourceKey":"maneuver:maneuvering-attack","key":"battle_master_maneuvering_attack","label":"Атака с манёвром","economy":"triggered","range":{"kind":"self"},"resourceCosts":[{"key":"superiority_dice","amount":1}]}],"menacing_attack":[{"id":"fighter-bm-maneuver-menace-feature","type":"grant","target":"feature","key":"subclass:fighter:battle-master:maneuver:menacing-attack","sourceKey":"maneuver:menacing-attack","payload":{"label":"Атака с угрозой","description":"Когда попадаете по существу атакой оружием, потратьте 1 кость превосходства и добавьте её к урону. Цель совершает спасбросок Мудрости; при провале испугана вами до конца вашего следующего хода."}},{"id":"fighter-bm-maneuver-menace-use","type":"action","sourceKey":"maneuver:menacing-attack","key":"battle_master_menacing_attack","label":"Атака с угрозой","economy":"triggered","range":{"kind":"self"},"resourceCosts":[{"key":"superiority_dice","amount":1}]}],"parry":[{"id":"fighter-bm-maneuver-parry-feature","type":"grant","target":"feature","key":"subclass:fighter:battle-master:maneuver:parry","sourceKey":"maneuver:parry","payload":{"label":"Парирование","description":"Когда другое существо наносит вам урон атакой ближнего боя, реакцией потратьте 1 кость превосходства и уменьшите урон на результат кости + модификатор Ловкости."}},{"id":"fighter-bm-maneuver-parry-use","type":"action","sourceKey":"maneuver:parry","key":"battle_master_parry","label":"Парирование","economy":"reaction","range":{"kind":"self"},"resourceCosts":[{"key":"superiority_dice","amount":1}]}],"precision_attack":[{"id":"fighter-bm-maneuver-precision-feature","type":"grant","target":"feature","key":"subclass:fighter:battle-master:maneuver:precision-attack","sourceKey":"maneuver:precision-attack","payload":{"label":"Точная атака","description":"Когда промахиваетесь броском атаки оружием, можно потратить 1 кость превосходства, бросить её и добавить результат к броску атаки, потенциально превращая промах в попадание."}},{"id":"fighter-bm-maneuver-precision-use","type":"action","sourceKey":"maneuver:precision-attack","key":"battle_master_precision_attack","label":"Точная атака","economy":"triggered","range":{"kind":"self"},"resourceCosts":[{"key":"superiority_dice","amount":1}]}],"pushing_attack":[{"id":"fighter-bm-maneuver-pushing-feature","type":"grant","target":"feature","key":"subclass:fighter:battle-master:maneuver:pushing-attack","sourceKey":"maneuver:pushing-attack","payload":{"label":"Толкающая атака","description":"Когда попадаете по существу атакой оружием, потратьте 1 кость превосходства и добавьте её к урону. Если цель Большая или меньше, она совершает спасбросок Силы; при провале её можно оттолкнуть от себя на расстояние до 15 футов."}},{"id":"fighter-bm-maneuver-pushing-use","type":"action","sourceKey":"maneuver:pushing-attack","key":"battle_master_pushing_attack","label":"Толкающая атака","economy":"triggered","range":{"kind":"self"},"resourceCosts":[{"key":"superiority_dice","amount":1}]}],"rally":[{"id":"fighter-bm-maneuver-rally-feature","type":"grant","target":"feature","key":"subclass:fighter:battle-master:maneuver:rally","sourceKey":"maneuver:rally","payload":{"label":"Сплочение","description":"Бонусным действием выберите дружественное существо, которое видит или слышит вас, и потратьте 1 кость превосходства. Оно получает временные HP, равные результату кости + модификатор Харизмы."}},{"id":"fighter-bm-maneuver-rally-use","type":"action","sourceKey":"maneuver:rally","key":"battle_master_rally","label":"Сплочение","economy":"bonus_action","range":{"kind":"self"},"resourceCosts":[{"key":"superiority_dice","amount":1}]}],"riposte":[{"id":"fighter-bm-maneuver-riposte-feature","type":"grant","target":"feature","key":"subclass:fighter:battle-master:maneuver:riposte","sourceKey":"maneuver:riposte","payload":{"label":"Ответный удар","description":"Когда существо промахивается по вам атакой ближнего боя, реакцией потратьте 1 кость превосходства и совершите одну атаку оружием ближнего боя по этому существу; при попадании добавьте кость превосходства к урону."}},{"id":"fighter-bm-maneuver-riposte-use","type":"action","sourceKey":"maneuver:riposte","key":"battle_master_riposte","label":"Ответный удар","economy":"reaction","range":{"kind":"self"},"resourceCosts":[{"key":"superiority_dice","amount":1}]}],"sweeping_attack":[{"id":"fighter-bm-maneuver-sweep-feature","type":"grant","target":"feature","key":"subclass:fighter:battle-master:maneuver:sweeping-attack","sourceKey":"maneuver:sweeping-attack","payload":{"label":"Рассекающая атака","description":"Когда попадаете по существу атакой оружием ближнего боя, потратьте 1 кость превосходства и выберите другое существо в пределах 5 футов от первоначальной цели и в вашей досягаемости. Если первоначальный бросок атаки попал бы и по второй цели, она получает урон, равный результату кости превосходства; тип урона тот же, что у исходной атаки."}},{"id":"fighter-bm-maneuver-sweep-use","type":"action","sourceKey":"maneuver:sweeping-attack","key":"battle_master_sweeping_attack","label":"Рассекающая атака","economy":"triggered","range":{"kind":"self"},"resourceCosts":[{"key":"superiority_dice","amount":1}]}],"tactical_assessment":[{"id":"fighter-bm-maneuver-assessment-feature","type":"grant","target":"feature","key":"subclass:fighter:battle-master:maneuver:tactical-assessment","sourceKey":"maneuver:tactical-assessment","payload":{"label":"Тактическая оценка","description":"Когда совершаете проверку Интеллекта (Расследование), Интеллекта (История) или Мудрости (Проницательность), можно потратить 1 кость превосходства и добавить её результат к проверке."}},{"id":"fighter-bm-maneuver-assessment-use","type":"action","sourceKey":"maneuver:tactical-assessment","key":"battle_master_tactical_assessment","label":"Тактическая оценка","economy":"triggered","range":{"kind":"self"},"resourceCosts":[{"key":"superiority_dice","amount":1}]}],"trip_attack":[{"id":"fighter-bm-maneuver-trip-feature","type":"grant","target":"feature","key":"subclass:fighter:battle-master:maneuver:trip-attack","sourceKey":"maneuver:trip-attack","payload":{"label":"Опрокидывающая атака","description":"Когда попадаете по существу атакой оружием, потратьте 1 кость превосходства и добавьте её к урону. Если цель Большая или меньше, она совершает спасбросок Силы; при провале становится Опрокинутой."}},{"id":"fighter-bm-maneuver-trip-use","type":"action","sourceKey":"maneuver:trip-attack","key":"battle_master_trip_attack","label":"Опрокидывающая атака","economy":"triggered","range":{"kind":"self"},"resourceCosts":[{"key":"superiority_dice","amount":1}]}}]}}'::jsonb));
    perform private.fighter_set_subclass_level_v2(v_battle_master,7,jsonb_build_array(
      private.fighter_feature('fighter-bm-know','know-your-enemy','subclass:fighter:battle-master:know-your-enemy','Познай своего врага','Бонусным действием выберите видимое существо в пределах 30 футов. Узнайте его иммунитеты, сопротивления и уязвимости к урону. 1 бесплатное использование за долгий отдых; после бесплатного использования способность можно восстановить без действия, потратив 1 кость превосходства.'),
      private.fighter_resource('fighter-bm-know-pool','know-your-enemy','know_your_enemy','Познай своего врага','1'::jsonb,'{"triggers":["long_rest"],"restore":"full"}'::jsonb,7,'REPLACE'),
      private.fighter_action('fighter-bm-know-use','know-your-enemy','know_your_enemy','Познай своего врага','bonus_action','[{"key":"know_your_enemy","amount":1}]'::jsonb),
      private.fighter_action('fighter-bm-know-restore','know-your-enemy','know_your_enemy_restore','Восстановить «Познай своего врага»','free','[{"key":"superiority_dice","amount":1}]'::jsonb,'[{"kind":"resource","key":"know_your_enemy","operation":"RESTORE","amount":1}]'::jsonb),
      private.fighter_resource('fighter-bm-dice-l7','combat-superiority','superiority_dice','Кости превосходства','5'::jsonb,'{"triggers":["short_rest","long_rest"],"restore":"full"}'::jsonb,7,'REPLACE')
    ));
    perform private.fighter_set_subclass_level_v2(v_battle_master,10,jsonb_build_array(private.fighter_value('fighter-bm-die-l10','combat-superiority','superiority_die','Кость превосходства','10'::jsonb,10,'REPLACE')));
    perform private.fighter_set_subclass_level_v2(v_battle_master,15,jsonb_build_array(
      private.fighter_feature('fighter-bm-relentless','relentless','subclass:fighter:battle-master:relentless','Неутомимость','Один раз за ход, когда используете приём, можно бросить 1к8 и использовать этот результат вместо траты кости превосходства.'),
      private.fighter_resource('fighter-bm-dice-l15','combat-superiority','superiority_dice','Кости превосходства','6'::jsonb,'{"triggers":["short_rest","long_rest"],"restore":"full"}'::jsonb,15,'REPLACE')
    ));
    perform private.fighter_set_subclass_level_v2(v_battle_master,18,jsonb_build_array(private.fighter_value('fighter-bm-die-l18','combat-superiority','superiority_die','Кость превосходства','12'::jsonb,18,'REPLACE')));
  end if;

  if v_cavalier is not null then
    update public.rule_templates set catalog_revision='xgte-2017-cavalier-ru-precision-v2',updated_at=now() where id=v_cavalier;
    perform private.fighter_patch_feature_text(v_cavalier,3,'unwavering-mark','Непоколебимая метка','Когда попадаете по существу атакой оружием ближнего боя, можно пометить его до конца вашего следующего хода. Пока помеченная цель находится в пределах 5 футов от вас, её атаки по другим существам совершаются с помехой. Если она нанесла урон кому-то кроме вас, на следующем ходу можно бонусным действием совершить особую атаку оружием ближнего боя по ней с преимуществом; при попадании добавьте урон, равный половине уровня Воина. Таких особых атак: модификатор Силы, минимум 1, за долгий отдых.');
    perform private.fighter_patch_feature_text(v_cavalier,7,'warding-maneuver','Защитный манёвр','Реакцией, когда вы или существо в пределах 5 футов от вас получает попадание атакой, бросьте 1к8 и добавьте результат к КД цели против этой атаки. Если атака всё равно попала, цель получает сопротивление урону этой атаки. Использований: модификатор Телосложения, минимум 1, за долгий отдых.');
    perform private.fighter_patch_feature_text(v_cavalier,10,'hold-the-line','Держать строй','Существа провоцируют вашу атаку по возможности, когда перемещаются на 5 футов или больше внутри вашей досягаемости. Если такая атака попадает, Скорость цели становится 0 до конца текущего хода.');
    perform private.fighter_patch_feature_text(v_cavalier,15,'ferocious-charger','Свирепый натиск','Если перед попаданием атакой оружием вы переместились по прямой не менее 10 футов, цель совершает спасбросок Силы против вашей Сл манёвров; при провале становится Опрокинутой.');
    perform private.fighter_patch_feature_text(v_cavalier,18,'vigilant-defender','Бдительный защитник','В бою вы получаете особую реакцию на каждом ходу другого существа. Эту специальную реакцию можно использовать только для атаки по возможности; обычную реакцию она не заменяет.');
  end if;

  if v_champion is not null then
    update public.rule_templates set catalog_revision='xphb-2024-champion-ru-precision-v2',updated_at=now() where id=v_champion;
    perform private.fighter_patch_feature_text(v_champion,3,'improved-critical','Улучшенные критические попадания','Ваши атаки оружием и безоружные удары наносят критическое попадание при результате 19 или 20 на к20.');
    perform private.fighter_patch_feature_text(v_champion,3,'remarkable-athlete','Выдающийся атлет','Получаете преимущество на броски инициативы и проверки Силы (Атлетика). Сразу после критического попадания можно переместиться на расстояние до половины Скорости, не провоцируя атаки по возможности.');
    perform private.fighter_patch_feature_text(v_champion,7,'additional-fighting-style','Дополнительный боевой стиль','Получите ещё один талант Боевого стиля, требованиям которого соответствуете.');
    perform private.fighter_patch_feature_text(v_champion,10,'heroic-warrior','Героический воин','Во время боя в начале своего хода, если у вас нет Героического вдохновения, вы получаете его.');
    perform private.fighter_patch_feature_text(v_champion,15,'superior-critical','Превосходные критические попадания','Ваши атаки оружием и безоружные удары наносят критическое попадание при результате 18–20 на к20.');
    perform private.fighter_patch_feature_text(v_champion,18,'survivor','Вызов смерти','Преимущество на спасброски от смерти; результат 18–20 на к20 считается результатом 20. Кроме того, в начале своего хода, если у вас хотя бы 1 HP и вы Окровавлены, восстановите 5 + модификатор Телосложения HP.');
  end if;

  if v_echo is not null then
    update public.rule_templates set catalog_revision='egtw-2020-echo-knight-ru-precision-v2',updated_at=now() where id=v_echo;
    perform private.fighter_patch_feature_text(v_echo,3,'manifest-echo','Проявление эха','Бонусным действием создайте магическое полупрозрачное эхо в свободном месте, которое видите в пределах 15 футов. У эха КД 14 + бонус мастерства, 1 HP и иммунитет ко всем состояниям. Оно использует ваши спасброски, занимает место и уничтожается, если оказывается дальше 30 футов от вас в конце вашего хода. На своём ходу можно мысленно перемещать его на 30 футов без действия. При действии Атака любая ваша атака может исходить из вашего места или места эха. Бонусным действием, потратив 15 футов движения, можно телепортироваться, поменявшись с эхом местами. Когда существо в 5 футах от эха отходит от него хотя бы на 5 футов, реакцией можно совершить по нему атаку по возможности как будто вы находитесь на месте эха.');
    perform private.fighter_patch_feature_text(v_echo,7,'echo-avatar','Аватар эха','Действием перенесите сознание в эхо. До 10 минут вы видите его глазами и слышите его ушами; в это время вы слепы и глухи к собственным чувствам. Пока способность действует, эхо может удаляться от вас до 1000 футов, не уничтожаясь из-за обычного ограничения 30 футов.');
    perform private.fighter_patch_feature_text(v_echo,18,'legion-of-one','Легион одного','Бонусным действием можно создать два эха вместо одного; они могут сосуществовать одновременно, но попытка создать третье уничтожает предыдущие. Всё, что можно делать из позиции одного эха, можно делать из позиции любого. Когда бросаете инициативу и Воплощений ярости не осталось, восстанавливаете 1 использование.');
  end if;

  if v_eldritch is not null then
    update public.rule_templates set
      catalog_revision='xphb-2024-eldritch-knight-ru-precision-v2',
      mechanical_summary='Мистический рыцарь 2024: Интеллект, заговоры и подготовленные заклинания Волшебника, общие ячейки персонажа, Связь с оружием и боевая магия. Число подготовленных заклинаний хранится отдельно от ячеек.',
      rules_meta=coalesce(rules_meta,'{}'::jsonb)||jsonb_build_object('spellcasting_progression','one_third','spell_list','wizard','spellcasting_ability','intelligence','spellcasting_enabled',true),
      updated_at=now()
    where id=v_eldritch;

    perform private.fighter_set_subclass_level_v2(v_eldritch,3,jsonb_build_array(
      private.fighter_feature('fighter-ek-casting','eldritch-knight-spellcasting','subclass:fighter:eldritch-knight:spellcasting','Сотворение заклинаний','Вы знаете 2 заговора Волшебника; на 10 уровне знаете 3. Интеллект — заклинательная характеристика, и можно использовать магическую фокусировку как заклинательную фокусировку. Подготавливайте заклинания Волшебника согласно таблице Мистического рыцаря; при повышении уровня Воина можно заменить одно подготовленное заклинание другим доступным заклинанием Волшебника.'),
      private.fighter_feature('fighter-ek-bond','weapon-bond','subclass:fighter:eldritch-knight:weapon-bond','Связь с оружием','Проведите 1-часовой ритуал с оружием в пределах досягаемости; ритуал можно провести во время короткого отдыха. Связь не создаётся, если оружие уже связано с другим Воином или является магическим предметом, настроенным на другое существо. Связанное оружие нельзя выбить у вас, пока вы не Недееспособны. Если оружие на том же плане, бонусным действием призовите его в руку. Одновременно можно иметь связь максимум с двумя оружиями; связь с третьим требует разорвать одну из первых двух.'),
      private.fighter_value('fighter-ek-prepared-l3','eldritch-knight-spellcasting','eldritch_knight_prepared_spells','Подготовленных заклинаний','3'::jsonb,3,'REPLACE'),
      private.fighter_value('fighter-ek-cantrips-l3','eldritch-knight-spellcasting','eldritch_knight_cantrips','Известных заговоров','2'::jsonb,3,'REPLACE'),
      private.fighter_resource('fighter-ek-slot1-l3','eldritch-knight-spellcasting','spell_slot_1','Ячейки 1 уровня','2'::jsonb,'{"triggers":["long_rest"],"restore":"full"}'::jsonb,3,'REPLACE')
    ));
    perform private.fighter_set_subclass_level_v2(v_eldritch,4,jsonb_build_array(
      private.fighter_value('fighter-ek-prepared-l4','eldritch-knight-spellcasting','eldritch_knight_prepared_spells','Подготовленных заклинаний','4'::jsonb,4,'REPLACE'),
      private.fighter_resource('fighter-ek-slot1-l4','eldritch-knight-spellcasting','spell_slot_1','Ячейки 1 уровня','3'::jsonb,'{"triggers":["long_rest"],"restore":"full"}'::jsonb,4,'REPLACE')
    ));
    perform private.fighter_set_subclass_level_v2(v_eldritch,7,jsonb_build_array(
      private.fighter_feature('fighter-ek-war-magic','war-magic','subclass:fighter:eldritch-knight:war-magic','Боевая магия','Когда совершаете действие Атака на своём ходу, можно заменить одну из атак накладыванием одного из ваших заговоров Волшебника с временем накладывания Действие.'),
      private.fighter_value('fighter-ek-prepared-l7','eldritch-knight-spellcasting','eldritch_knight_prepared_spells','Подготовленных заклинаний','5'::jsonb,7,'REPLACE'),
      private.fighter_resource('fighter-ek-slot1-l7','eldritch-knight-spellcasting','spell_slot_1','Ячейки 1 уровня','4'::jsonb,'{"triggers":["long_rest"],"restore":"full"}'::jsonb,7,'REPLACE'),
      private.fighter_resource('fighter-ek-slot2-l7','eldritch-knight-spellcasting','spell_slot_2','Ячейки 2 уровня','2'::jsonb,'{"triggers":["long_rest"],"restore":"full"}'::jsonb,7,'REPLACE')
    ));
    perform private.fighter_set_subclass_level_v2(v_eldritch,8,jsonb_build_array(private.fighter_value('fighter-ek-prepared-l8','eldritch-knight-spellcasting','eldritch_knight_prepared_spells','Подготовленных заклинаний','6'::jsonb,8,'REPLACE')));
    perform private.fighter_set_subclass_level_v2(v_eldritch,10,jsonb_build_array(
      private.fighter_feature('fighter-ek-strike','eldritch-strike','subclass:fighter:eldritch-knight:eldritch-strike','Мистический удар','Когда попадаете по существу атакой оружием, оно получает помеху на следующий спасбросок против заклинания, которое вы наложите до конца вашего следующего хода.'),
      private.fighter_value('fighter-ek-prepared-l10','eldritch-knight-spellcasting','eldritch_knight_prepared_spells','Подготовленных заклинаний','7'::jsonb,10,'REPLACE'),
      private.fighter_value('fighter-ek-cantrips-l10','eldritch-knight-spellcasting','eldritch_knight_cantrips','Известных заговоров','3'::jsonb,10,'REPLACE'),
      private.fighter_resource('fighter-ek-slot2-l10','eldritch-knight-spellcasting','spell_slot_2','Ячейки 2 уровня','3'::jsonb,'{"triggers":["long_rest"],"restore":"full"}'::jsonb,10,'REPLACE')
    ));
    perform private.fighter_set_subclass_level_v2(v_eldritch,11,jsonb_build_array(private.fighter_value('fighter-ek-prepared-l11','eldritch-knight-spellcasting','eldritch_knight_prepared_spells','Подготовленных заклинаний','8'::jsonb,11,'REPLACE')));
    perform private.fighter_set_subclass_level_v2(v_eldritch,13,jsonb_build_array(
      private.fighter_value('fighter-ek-prepared-l13','eldritch-knight-spellcasting','eldritch_knight_prepared_spells','Подготовленных заклинаний','9'::jsonb,13,'REPLACE'),
      private.fighter_resource('fighter-ek-slot3-l13','eldritch-knight-spellcasting','spell_slot_3','Ячейки 3 уровня','2'::jsonb,'{"triggers":["long_rest"],"restore":"full"}'::jsonb,13,'REPLACE')
    ));
    perform private.fighter_set_subclass_level_v2(v_eldritch,14,jsonb_build_array(private.fighter_value('fighter-ek-prepared-l14','eldritch-knight-spellcasting','eldritch_knight_prepared_spells','Подготовленных заклинаний','10'::jsonb,14,'REPLACE')));
    perform private.fighter_set_subclass_level_v2(v_eldritch,15,jsonb_build_array(private.fighter_feature('fighter-ek-charge','arcane-charge','subclass:fighter:eldritch-knight:arcane-charge','Волшебный рывок','Когда используете Всплеск действий, можно телепортироваться на расстояние до 30 футов в свободное место, которое видите. Телепортация происходит до или после дополнительного действия Всплеска действий.')));
    perform private.fighter_set_subclass_level_v2(v_eldritch,16,jsonb_build_array(
      private.fighter_value('fighter-ek-prepared-l16','eldritch-knight-spellcasting','eldritch_knight_prepared_spells','Подготовленных заклинаний','11'::jsonb,16,'REPLACE'),
      private.fighter_resource('fighter-ek-slot3-l16','eldritch-knight-spellcasting','spell_slot_3','Ячейки 3 уровня','3'::jsonb,'{"triggers":["long_rest"],"restore":"full"}'::jsonb,16,'REPLACE')
    ));
    perform private.fighter_set_subclass_level_v2(v_eldritch,18,jsonb_build_array(private.fighter_feature('fighter-ek-improved-war','improved-war-magic','subclass:fighter:eldritch-knight:improved-war-magic','Улучшенная боевая магия','Когда совершаете действие Атака на своём ходу, можно заменить две атаки накладыванием одного подготовленного заклинания Волшебника 1 или 2 уровня с временем накладывания Действие. Ячейка тратится обычным способом.')));
    perform private.fighter_set_subclass_level_v2(v_eldritch,19,jsonb_build_array(
      private.fighter_value('fighter-ek-prepared-l19','eldritch-knight-spellcasting','eldritch_knight_prepared_spells','Подготовленных заклинаний','12'::jsonb,19,'REPLACE'),
      private.fighter_resource('fighter-ek-slot4-l19','eldritch-knight-spellcasting','spell_slot_4','Ячейки 4 уровня','1'::jsonb,'{"triggers":["long_rest"],"restore":"full"}'::jsonb,19,'REPLACE')
    ));
    perform private.fighter_set_subclass_level_v2(v_eldritch,20,jsonb_build_array(private.fighter_value('fighter-ek-prepared-l20','eldritch-knight-spellcasting','eldritch_knight_prepared_spells','Подготовленных заклинаний','13'::jsonb,20,'REPLACE')));
  end if;

  if v_psi is not null then
    update public.rule_templates set
      catalog_revision='xphb-2024-psi-warrior-ru-precision-v2',
      mechanical_summary='Пси-воин 2024: число и размер Костей пси-энергии следуют таблице уровня Воина; после короткого отдыха возвращается 1 потраченная кость, после долгого — весь запас.',
      updated_at=now()
    where id=v_psi;
    perform private.fighter_set_subclass_level_v2(v_psi,3,jsonb_build_array(
      private.fighter_feature('fighter-psi-power','psionic-power','subclass:fighter:psi-warrior:power','Псионическая сила','Кости пси-энергии — отдельный запас. На 3 уровне у вас 4к6. Защитное поле, Псионический удар и Телекинетическое передвижение расходуют кость только когда вы действительно используете соответствующую способность. После короткого отдыха восстановите 1 потраченную Кость пси-энергии; после долгого отдыха восстановите весь запас.'),
      private.fighter_resource('fighter-psi-pool-l3','psionic-power','psionic_energy','Кости пси-энергии','4'::jsonb,'{"triggers":["long_rest"],"restore":"full"}'::jsonb,3,'REPLACE','[{"trigger":"short_rest","restore":"amount","amount":1},{"trigger":"long_rest","restore":"full"}]'::jsonb),
      private.fighter_value('fighter-psi-die3','psionic-power','psionic_die','Кость пси-энергии','6'::jsonb,3,'REPLACE')
    ));
    perform private.fighter_set_subclass_level_v2(v_psi,5,jsonb_build_array(
      private.fighter_resource('fighter-psi-pool-l5','psionic-power','psionic_energy','Кости пси-энергии','6'::jsonb,'{"triggers":["long_rest"],"restore":"full"}'::jsonb,5,'REPLACE','[{"trigger":"short_rest","restore":"amount","amount":1},{"trigger":"long_rest","restore":"full"}]'::jsonb),
      private.fighter_value('fighter-psi-die5','psionic-power','psionic_die','Кость пси-энергии','8'::jsonb,5,'REPLACE')
    ));
    perform private.fighter_set_subclass_level_v2(v_psi,7,jsonb_build_array(private.fighter_feature('fighter-psi-adept','telekinetic-adept','subclass:fighter:psi-warrior:adept','Телекинетический адепт','Получаете Усиленный пси-прыжок и Телекинетический толчок. Усиленный пси-прыжок: бонусным действием получите Скорость полёта, равную удвоенной Скорости ходьбы, до конца текущего хода. Телекинетический толчок: когда наносите урон Псионическим ударом, цель Большого размера или меньше совершает спасбросок Силы; при провале можно Опрокинуть её или переместить на 10 футов по горизонтали.')));
    perform private.fighter_set_subclass_level_v2(v_psi,9,jsonb_build_array(private.fighter_resource('fighter-psi-pool-l9','psionic-power','psionic_energy','Кости пси-энергии','8'::jsonb,'{"triggers":["long_rest"],"restore":"full"}'::jsonb,9,'REPLACE','[{"trigger":"short_rest","restore":"amount","amount":1},{"trigger":"long_rest","restore":"full"}]'::jsonb)));
    perform private.fighter_set_subclass_level_v2(v_psi,10,jsonb_build_array(private.fighter_feature('fighter-psi-mind','guarded-mind','subclass:fighter:psi-warrior:guarded-mind','Защищённый разум','Получаете сопротивление психическому урону. В начале своего хода, если вы Очарованы или Испуганы, можно потратить 1 Кость пси-энергии и завершить на себе каждый эффект, вызывающий одно из этих состояний.')));
    perform private.fighter_set_subclass_level_v2(v_psi,11,jsonb_build_array(private.fighter_value('fighter-psi-die11','psionic-power','psionic_die','Кость пси-энергии','10'::jsonb,11,'REPLACE')));
    perform private.fighter_set_subclass_level_v2(v_psi,13,jsonb_build_array(private.fighter_resource('fighter-psi-pool-l13','psionic-power','psionic_energy','Кости пси-энергии','10'::jsonb,'{"triggers":["long_rest"],"restore":"full"}'::jsonb,13,'REPLACE','[{"trigger":"short_rest","restore":"amount","amount":1},{"trigger":"long_rest","restore":"full"}]'::jsonb)));
    perform private.fighter_set_subclass_level_v2(v_psi,15,jsonb_build_array(private.fighter_feature('fighter-psi-bulwark','bulwark-of-force','subclass:fighter:psi-warrior:bulwark','Оплот силы','Бонусным действием выберите существ, включая себя, в пределах 30 футов, числом до модификатора Интеллекта, минимум 1. Каждое выбранное существо получает укрытие наполовину на 1 минуту или пока вы Недееспособны. Одно применение бесплатно за долгий отдых; повторное применение требует потратить 1 Кость пси-энергии.')));
    perform private.fighter_set_subclass_level_v2(v_psi,17,jsonb_build_array(
      private.fighter_resource('fighter-psi-pool-l17','psionic-power','psionic_energy','Кости пси-энергии','12'::jsonb,'{"triggers":["long_rest"],"restore":"full"}'::jsonb,17,'REPLACE','[{"trigger":"short_rest","restore":"amount","amount":1},{"trigger":"long_rest","restore":"full"}]'::jsonb),
      private.fighter_value('fighter-psi-die17','psionic-power','psionic_die','Кость пси-энергии','12'::jsonb,17,'REPLACE')
    ));
    perform private.fighter_set_subclass_level_v2(v_psi,18,jsonb_build_array(private.fighter_feature('fighter-psi-master','telekinetic-master','subclass:fighter:psi-warrior:master','Мастер телекинеза','Вы можете накладывать Телекинез без компонентов; Интеллект — заклинательная характеристика. Одно применение бесплатно за долгий отдых; повторное применение до следующего долгого отдыха требует потратить 1 Кость пси-энергии. Пока концентрируетесь на Телекинезе, бонусным действием можно совершить одну атаку оружием.')));
  end if;

  if v_banneret is not null then
    update public.rule_templates set
      catalog_revision='frhof-2025-banneret-ru-precision-v2',
      mechanical_summary='Баннерет расширяет ресурсы базового Воина: Групповое оздоровление с отдельным 1/отдых лимитом, Воодушевляющий всплеск через Всплеск действий и Устойчивость команды через Неукротимого.',
      updated_at=now()
    where id=v_banneret;
    perform private.fighter_set_subclass_level_v2(v_banneret,3,jsonb_build_array(
      private.fighter_feature('fighter-ban-envoy','knightly-envoy','subclass:fighter:banneret:envoy','Посланник рыцарства','Получаете Понимание, Полиглота и Поставленную речь согласно подклассу.'),
      private.fighter_feature('fighter-ban-recovery','group-recovery','subclass:fighter:banneret:group-recovery','Групповое оздоровление','Когда используете Второе дыхание и восстанавливаете себе HP, выберите союзников в 30-футовой эманации числом до модификатора Харизмы, минимум 1. Каждый выбранный союзник восстанавливает 1к4 + уровень Воина HP. 1 использование за короткий или долгий отдых; само Второе дыхание расходуется обычным способом.'),
      private.fighter_resource('fighter-ban-recovery-pool','group-recovery','group_recovery','Групповое оздоровление','1'::jsonb,'{"triggers":["short_rest","long_rest"],"restore":"full"}'::jsonb,3,'REPLACE')
    ));
    perform private.fighter_set_subclass_level_v2(v_banneret,7,jsonb_build_array(private.fighter_feature('fighter-ban-team','team-tactics','subclass:fighter:banneret:team-tactics','Групповая тактика','Союзники, выбранные Групповым оздоровлением, получают преимущество на проверки к20 до начала вашего следующего хода.')));
    perform private.fighter_set_subclass_level_v2(v_banneret,10,jsonb_build_array(private.fighter_feature('fighter-ban-surge','rallying-surge','subclass:fighter:banneret:rallying-surge','Воодушевляющий всплеск','Когда используете Всплеск действий, выберите союзников в пределах 30 футов числом до модификатора Харизмы, минимум 1. Каждый выбранный союзник может реакцией либо совершить одну атаку оружием, либо переместиться на расстояние до половины своей Скорости, не провоцируя атаки по возможности. Отдельный ресурс не создаётся: расходуется Всплеск действий.')));
    perform private.fighter_set_subclass_level_v2(v_banneret,15,jsonb_build_array(private.fighter_feature('fighter-ban-resilience','shared-resilience','subclass:fighter:banneret:shared-resilience','Устойчивость команды','Когда видимый союзник в пределах 60 футов проваливает спасбросок, реакцией потратьте 1 использование Неукротимого. Союзник перебрасывает спасбросок, добавляет к новому результату ваш уровень Воина и обязан использовать новый результат.')));
    perform private.fighter_set_subclass_level_v2(v_banneret,18,jsonb_build_array(private.fighter_feature('fighter-ban-command','inspiring-commander','subclass:fighter:banneret:commander','Вдохновляющий командир','Дальность Группового оздоровления и Воодушевляющего всплеска увеличивается до 60 футов. Союзники в пределах 60 футов от вас имеют иммунитет к состояниям Очарованный и Испуганный, пока вы не Недееспособны.')));
  end if;

  if v_rune is not null then
    update public.rule_templates set
      catalog_revision='tcoe-2020-rune-knight-ru-precision-v2',
      mechanical_summary='Рунный рыцарь: каждая выбранная руна — отдельная механическая идентичность и отдельный запас; выбор рун растёт 2→3→4→5, Холмовая и Штормовая открываются с 7 уровня.',
      updated_at=now()
    where id=v_rune;

    perform private.fighter_set_subclass_level_v2(v_rune,3,jsonb_build_array(
      private.fighter_feature('fighter-rune-might','giants-might','subclass:fighter:rune-knight:giants-might','Мощь великана','Бонусным действием на 1 минуту, если вы меньше Большого размера, становитесь Большим вместе со всем надетым; получаете преимущество на проверки Силы и спасброски Силы; один раз на каждом своём ходу при попадании атакой оружием или безоружным ударом наносите дополнительно 1к6 урона. Использований: бонус мастерства за долгий отдых.'),
      private.fighter_feature('fighter-rune-carver','rune-carver','subclass:fighter:rune-knight:runes','Рунный резчик','После долгого отдыха нанесите каждую известную руну на отдельное оружие, броню, щит, украшение или другой предмет, который носите или держите. Чтобы пользоваться пассивным и активным эффектом руны, нужно носить или держать предмет с ней.'),
      private.fighter_resource('fighter-rune-might-pool','giants-might','giants_might','Мощь великана','{"kind":"reference","key":"core.proficiencyBonus"}'::jsonb,'{"triggers":["long_rest"],"restore":"full"}'::jsonb,3,'REPLACE')
    ),jsonb_build_array('{"key":"rune_knight_runes","label":"Руны Рунного рыцаря","target":"trait","options":["cloud","fire","frost","stone","hill","storm"],"count":2,"count_by_level":{"7":3,"10":4,"15":5},"option_unlock_level":{"hill":7,"storm":7},"option_labels":{"cloud":"Облачная руна","fire":"Огненная руна","frost":"Ледяная руна","stone":"Каменная руна","hill":"Холмовая руна","storm":"Штормовая руна"},"option_mechanics":{"cloud":[{"id":"fighter-rune-cloud-feature","type":"grant","target":"feature","key":"subclass:fighter:rune-knight:rune:cloud","sourceKey":"rune:cloud","payload":{"label":"Облачная руна","description":"Пока вы носите или держите предмет с этой руной, проверки Ловкости (Ловкость рук) и Харизмы (Обман) совершаются с преимуществом. Когда вы или видимое существо в пределах 30 футов получает попадание атакой, реакцией активируйте руну и выберите другое существо в пределах 30 футов от себя: выбранное существо становится новой целью той же атаки с тем же броском атаки."}},{"id":"fighter-rune-cloud-pool","type":"grant","target":"resource","key":"rune_cloud","sourceKey":"rune:cloud","grantOperation":"REPLACE","priority":3,"payload":{"max":1,"label":"Облачная руна","initial":"full","recharge":{"triggers":["short_rest","long_rest"],"restore":"full"}}},{"id":"fighter-rune-cloud-use","type":"action","sourceKey":"rune:cloud","key":"rune_cloud","label":"Облачная руна","economy":"reaction","range":{"kind":"self"},"presentation":{"tone":"amber","icon":"◆","display":"counter","priority":85},"resourceCosts":[{"key":"rune_cloud","amount":1}],"tags":["rune_knight","rune"]}],"fire":[{"id":"fighter-rune-fire-feature","type":"grant","target":"feature","key":"subclass:fighter:rune-knight:rune:fire","sourceKey":"rune:fire","payload":{"label":"Огненная руна","description":"Пока вы носите или держите предмет с этой руной, бонус мастерства удваивается для проверок характеристик с инструментом, которым вы владеете. После попадания атакой оружием активируйте руну: цель получает +2к6 огненного урона и совершает спасбросок Силы; при провале опутана огненными оковами на 1 минуту и получает 2к6 огненного урона в начале каждого своего хода, повторяя спасбросок в конце хода до успеха."}},{"id":"fighter-rune-fire-pool","type":"grant","target":"resource","key":"rune_fire","sourceKey":"rune:fire","grantOperation":"REPLACE","priority":3,"payload":{"max":1,"label":"Огненная руна","initial":"full","recharge":{"triggers":["short_rest","long_rest"],"restore":"full"}}},{"id":"fighter-rune-fire-use","type":"action","sourceKey":"rune:fire","key":"rune_fire","label":"Огненная руна","economy":"triggered","range":{"kind":"self"},"presentation":{"tone":"amber","icon":"◆","display":"counter","priority":85},"resourceCosts":[{"key":"rune_fire","amount":1}],"tags":["rune_knight","rune"]}],"frost":[{"id":"fighter-rune-frost-feature","type":"grant","target":"feature","key":"subclass:fighter:rune-knight:rune:frost","sourceKey":"rune:frost","payload":{"label":"Ледяная руна","description":"Пока вы носите или держите предмет с этой руной, проверки Мудрости (Уход за животными) и Харизмы (Запугивание) совершаются с преимуществом. Бонусным действием активируйте руну: на 10 минут получаете +2 ко всем проверкам характеристик и спасброскам, использующим Силу или Телосложение."}},{"id":"fighter-rune-frost-pool","type":"grant","target":"resource","key":"rune_frost","sourceKey":"rune:frost","grantOperation":"REPLACE","priority":3,"payload":{"max":1,"label":"Ледяная руна","initial":"full","recharge":{"triggers":["short_rest","long_rest"],"restore":"full"}}},{"id":"fighter-rune-frost-use","type":"action","sourceKey":"rune:frost","key":"rune_frost","label":"Ледяная руна","economy":"bonus_action","range":{"kind":"self"},"presentation":{"tone":"amber","icon":"◆","display":"counter","priority":85},"resourceCosts":[{"key":"rune_frost","amount":1}],"tags":["rune_knight","rune"]}],"stone":[{"id":"fighter-rune-stone-feature","type":"grant","target":"feature","key":"subclass:fighter:rune-knight:rune:stone","sourceKey":"rune:stone","payload":{"label":"Каменная руна","description":"Пока вы носите или держите предмет с этой руной, проверки Мудрости (Проницательность) совершаются с преимуществом, а тёмное зрение имеет дальность 120 футов. Когда видимое существо заканчивает ход в пределах 30 футов, реакцией активируйте руну: оно совершает спасбросок Мудрости; при провале на 1 минуту очаровано вами, недееспособно и имеет Скорость 0, повторяя спасбросок в конце каждого своего хода."}},{"id":"fighter-rune-stone-pool","type":"grant","target":"resource","key":"rune_stone","sourceKey":"rune:stone","grantOperation":"REPLACE","priority":3,"payload":{"max":1,"label":"Каменная руна","initial":"full","recharge":{"triggers":["short_rest","long_rest"],"restore":"full"}}},{"id":"fighter-rune-stone-use","type":"action","sourceKey":"rune:stone","key":"rune_stone","label":"Каменная руна","economy":"reaction","range":{"kind":"self"},"presentation":{"tone":"amber","icon":"◆","display":"counter","priority":85},"resourceCosts":[{"key":"rune_stone","amount":1}],"tags":["rune_knight","rune"]}],"hill":[{"id":"fighter-rune-hill-feature","type":"grant","target":"feature","key":"subclass:fighter:rune-knight:rune:hill","sourceKey":"rune:hill","payload":{"label":"Холмовая руна","description":"Требуется 7 уровень Воина. Пока вы носите или держите предмет с этой руной, спасброски против отравления совершаются с преимуществом и есть сопротивление урону ядом. Бонусным действием активируйте руну: на 1 минуту получаете сопротивление дробящему, колющему и рубящему урону."}},{"id":"fighter-rune-hill-pool","type":"grant","target":"resource","key":"rune_hill","sourceKey":"rune:hill","grantOperation":"REPLACE","priority":3,"payload":{"max":1,"label":"Холмовая руна","initial":"full","recharge":{"triggers":["short_rest","long_rest"],"restore":"full"}}},{"id":"fighter-rune-hill-use","type":"action","sourceKey":"rune:hill","key":"rune_hill","label":"Холмовая руна","economy":"bonus_action","range":{"kind":"self"},"presentation":{"tone":"amber","icon":"◆","display":"counter","priority":85},"resourceCosts":[{"key":"rune_hill","amount":1}],"tags":["rune_knight","rune"]}],"storm":[{"id":"fighter-rune-storm-feature","type":"grant","target":"feature","key":"subclass:fighter:rune-knight:rune:storm","sourceKey":"rune:storm","payload":{"label":"Штормовая руна","description":"Требуется 7 уровень Воина. Пока вы носите или держите предмет с этой руной, проверки Интеллекта (Магия) совершаются с преимуществом, и вас нельзя застать врасплох, пока вы не недееспособны. Бонусным действием активируйте руну на 1 минуту; пока эффект действует, реакцией, когда вы или видимое существо в пределах 60 футов совершает бросок атаки, спасбросок или проверку характеристики, можно дать этому броску преимущество или помеху."}},{"id":"fighter-rune-storm-pool","type":"grant","target":"resource","key":"rune_storm","sourceKey":"rune:storm","grantOperation":"REPLACE","priority":3,"payload":{"max":1,"label":"Штормовая руна","initial":"full","recharge":{"triggers":["short_rest","long_rest"],"restore":"full"}}},{"id":"fighter-rune-storm-use","type":"action","sourceKey":"rune:storm","key":"rune_storm","label":"Штормовая руна","economy":"bonus_action","range":{"kind":"self"},"presentation":{"tone":"amber","icon":"◆","display":"counter","priority":85},"resourceCosts":[{"key":"rune_storm","amount":1}],"tags":["rune_knight","rune"]}]} ,"option_mechanics_by_level":{"cloud":{"15":[{"id":"fighter-rune-cloud-pool-l15","type":"grant","target":"resource","key":"rune_cloud","sourceKey":"rune:cloud","grantOperation":"REPLACE","priority":15,"payload":{"max":2,"label":"Облачная руна","initial":"full","recharge":{"triggers":["short_rest","long_rest"],"restore":"full"}}}]},"fire":{"15":[{"id":"fighter-rune-fire-pool-l15","type":"grant","target":"resource","key":"rune_fire","sourceKey":"rune:fire","grantOperation":"REPLACE","priority":15,"payload":{"max":2,"label":"Огненная руна","initial":"full","recharge":{"triggers":["short_rest","long_rest"],"restore":"full"}}}]},"frost":{"15":[{"id":"fighter-rune-frost-pool-l15","type":"grant","target":"resource","key":"rune_frost","sourceKey":"rune:frost","grantOperation":"REPLACE","priority":15,"payload":{"max":2,"label":"Ледяная руна","initial":"full","recharge":{"triggers":["short_rest","long_rest"],"restore":"full"}}}]},"stone":{"15":[{"id":"fighter-rune-stone-pool-l15","type":"grant","target":"resource","key":"rune_stone","sourceKey":"rune:stone","grantOperation":"REPLACE","priority":15,"payload":{"max":2,"label":"Каменная руна","initial":"full","recharge":{"triggers":["short_rest","long_rest"],"restore":"full"}}}]},"hill":{"15":[{"id":"fighter-rune-hill-pool-l15","type":"grant","target":"resource","key":"rune_hill","sourceKey":"rune:hill","grantOperation":"REPLACE","priority":15,"payload":{"max":2,"label":"Холмовая руна","initial":"full","recharge":{"triggers":["short_rest","long_rest"],"restore":"full"}}}]},"storm":{"15":[{"id":"fighter-rune-storm-pool-l15","type":"grant","target":"resource","key":"rune_storm","sourceKey":"rune:storm","grantOperation":"REPLACE","priority":15,"payload":{"max":2,"label":"Штормовая руна","initial":"full","recharge":{"triggers":["short_rest","long_rest"],"restore":"full"}}}]}}}'::jsonb));
    perform private.fighter_set_subclass_level_v2(v_rune,7,jsonb_build_array(
      private.fighter_feature('fighter-rune-shield','runic-shield','subclass:fighter:rune-knight:runic-shield','Рунический щит','Когда другое видимое существо в пределах 60 футов получает попадание броском атаки, реакцией заставьте атакующего перебросить к20 и использовать новый результат. Использований: бонус мастерства за долгий отдых.'),
      private.fighter_resource('fighter-rune-shield-pool','runic-shield','runic_shield','Рунический щит','{"kind":"reference","key":"core.proficiencyBonus"}'::jsonb,'{"triggers":["long_rest"],"restore":"full"}'::jsonb,7,'REPLACE')
    ));
    perform private.fighter_set_subclass_level_v2(v_rune,10,jsonb_build_array(private.fighter_feature('fighter-rune-stature','great-stature','subclass:fighter:rune-knight:stature','Великий рост','При получении этой способности ваш рост увеличивается на 3к4 дюйма. Кроме того, дополнительный урон Мощи великана становится 1к8.')));
    perform private.fighter_set_subclass_level_v2(v_rune,15,jsonb_build_array(private.fighter_feature('fighter-rune-master','master-of-runes','subclass:fighter:rune-knight:master','Мастер рун','Каждую известную руну теперь можно активировать дважды между короткими или долгими отдыхами вместо одного раза. Запасы отдельных рун остаются независимыми.')));
    perform private.fighter_set_subclass_level_v2(v_rune,18,jsonb_build_array(private.fighter_feature('fighter-rune-juggernaut','runic-juggernaut','subclass:fighter:rune-knight:juggernaut','Рунический джаггернаут','Мощь великана усиливается: если вы меньше Огромного размера, становитесь Огромным; досягаемость увеличивается на 5 футов; дополнительный урон Мощи великана становится 1к10.')));
  end if;

  if v_samurai is not null then
    update public.rule_templates set catalog_revision='xgte-2017-samurai-ru-precision-v2',updated_at=now() where id=v_samurai;
    perform private.fighter_set_subclass_level_v2(v_samurai,3,jsonb_build_array(
      private.fighter_feature('fighter-sam-spirit','fighting-spirit','subclass:fighter:samurai:fighting-spirit','Боевой дух','Бонусным действием получите преимущество на все атаки оружием до конца текущего хода и 5 временных HP. На 10 уровне временных HP становится 10, на 15 — 15. 3 использования за долгий отдых.'),
      private.fighter_resource('fighter-sam-spirit-pool','fighting-spirit','fighting_spirit','Боевой дух','3'::jsonb,'{"triggers":["long_rest"],"restore":"full"}'::jsonb,3,'REPLACE')
    ));
    perform private.fighter_patch_feature_text(v_samurai,7,'elegant-courtier','Элегантный придворный','Добавляйте модификатор Мудрости к проверкам Харизмы (Убеждение). Также получаете владение спасбросками Мудрости; если уже владеете ими, получите владение спасбросками Интеллекта или Харизмы на выбор.');
    perform private.fighter_patch_feature_text(v_samurai,10,'tireless-spirit','Неутомимая душа','Если при броске инициативы у вас не осталось использований Боевого духа, восстановите 1 использование.');
    perform private.fighter_patch_feature_text(v_samurai,15,'rapid-strike','Стремительный удар','Один раз за свой ход, если атака оружием совершается с преимуществом, можно отказаться от преимущества этой атаки и вместо этого сделать ещё одну атаку оружием по той же цели в рамках того же действия.');
    perform private.fighter_patch_feature_text(v_samurai,18,'strength-before-death','Стойкость перед смертью','Если урон опускает ваши HP до 0, но не убивает мгновенно, реакцией задержите потерю сознания и немедленно совершите дополнительный ход, прервав текущий. Пока длится этот дополнительный ход, вы имеете 0 HP и не теряете сознание; получение урона вызывает провалы спасбросков от смерти как обычно, а три провала могут убить вас. Когда дополнительный ход заканчивается, вы теряете сознание, если всё ещё имеете 0 HP. 1 использование за долгий отдых.');
  end if;

  update public.rule_templates set updated_at=now()
  where id in (v_arcane_archer,v_battle_master,v_cavalier,v_champion,v_echo,v_eldritch,v_psi,v_banneret,v_rune,v_samurai);
end;
$$;

create or replace function private.apply_fighter_completion_after_campaign()
returns trigger language plpgsql security definer set search_path='' as $$
begin
  perform private.apply_fighter_completion(new.id);
  return new;
end;
$$;

drop trigger if exists zzzzzzz_campaigns_fighter_completion on public.campaigns;
create trigger zzzzzzz_campaigns_fighter_completion
after insert on public.campaigns
for each row execute function private.apply_fighter_completion_after_campaign();

do $$ declare r record; begin
  for r in select id from public.campaigns loop
    perform private.apply_fighter_completion(r.id);
  end loop;
end $$;

commit;